//! Complex Γ and ψ at dest p 1920..2240 against mpmath 1.3.0 (`~/team-env/mpmath-1.3.0`, generated by
//! `scripts/gen_complex_gamma_high_p_goldens.py`): every part must equal the correctly rounded
//! p-bit value. From dest p 1984 the gamma shift target is k = 22 (`gamma_shift_exp`), so the
//! shifts from a small |z| run past 2^20; these inputs were answered at 5227f77d and must not be
//! refused with `PrecisionRetryExhausted` (Spence F1, 2026-11-13). Inputs are exact dyadics n·2^e.
//! Not here: complex ln Γ at p >= 2048 (takes more than 900 s, pre-existing, separate PR).

use zenith_float_num::{Consts, ExactComplex, ExactNum, Radix, RoundingMode, Word};

type Part = (bool, &'static str, i64);

/// (name, function, p, mode, re input (n, e), im input (n, e), want re, want im);
/// a want part (neg, hex mantissa, e) is ±mantissa·2^e.
#[rustfmt::skip]
const CASES: &[(&str, &str, usize, RoundingMode, (i64, i64), (i64, i64), Part, Part)] = &[
    ("gamma_three_quarters_quarter_i_p1920", "gamma", 1920, RoundingMode::ToEven, (3, -2), (1, -2), (false, "", -1919), (true, "", -1921)),
    ("gamma_three_quarters_quarter_i_p1984", "gamma", 1984, RoundingMode::ToEven, (3, -2), (1, -2), (false, "", -1981), (true, "", -1985)),
    ("gamma_three_quarters_quarter_i_p2048", "gamma", 2048, RoundingMode::ToEven, (3, -2), (1, -2), (false, "", -2046), (true, "", -2049)),
    ("gamma_three_quarters_minus_quarter_i_p1984", "gamma", 1984, RoundingMode::ToEven, (3, -2), (-1, -2), (false, "", -1981), (false, "", -1985)),
    ("gamma_tiny_real_p2048_to_even", "gamma", 2048, RoundingMode::ToEven, (1, -42), (0, 0), (false, "", -2002), (false, "0", 0)),
    ("gamma_tiny_real_p2048_up", "gamma", 2048, RoundingMode::Up, (1, -42), (0, 0), (false, "", -2006), (false, "0", 0)),
    ("gamma_tiny_real_p2048_down", "gamma", 2048, RoundingMode::Down, (1, -42), (0, 0), (false, "", -2002), (false, "0", 0)),
    ("gamma_tiny_real_p2048_to_zero", "gamma", 2048, RoundingMode::ToZero, (1, -42), (0, 0), (false, "", -2002), (false, "0", 0)),
    ("gamma_tiny_real_p2048_from_zero", "gamma", 2048, RoundingMode::FromZero, (1, -42), (0, 0), (false, "", -2006), (false, "0", 0)),
    ("gamma_tiny_real_p2240", "gamma", 2240, RoundingMode::ToEven, (1, -42), (0, 0), (false, "", -2198), (false, "0", 0)),
    ("gamma_tiny_imag_p1984", "gamma", 1984, RoundingMode::ToEven, (0, 0), (1, -10), (true, "", -1980), (true, "", -1970)),
    ("gamma_two_pow_20_minus_1_p2048", "gamma", 2048, RoundingMode::ToEven, (1048575, 0), (1, -1), (false, "", 19456670), (false, "", 19456668)),
    ("gamma_two_pow_20_plus_1_p2048", "gamma", 2048, RoundingMode::ToEven, (1048577, 0), (1, -1), (false, "", 19456708), (false, "", 19456708)),
    ("gamma_two_pow_21_minus_1_p1984", "gamma", 1984, RoundingMode::ToEven, (2097151, 0), (1, -1), (false, "", 41012629), (false, "", 41012629)),
    ("gamma_two_pow_21_plus_1_p1984", "gamma", 1984, RoundingMode::ToEven, (2097153, 0), (1, -1), (false, "", 41012670), (false, "", 41012669)),
    ("digamma_three_quarters_quarter_i_p2048", "digamma", 2048, RoundingMode::ToEven, (3, -2), (1, -2), (true, "", -2046), (false, "", -2048)),
    ("digamma_tiny_real_p2048", "digamma", 2048, RoundingMode::ToEven, (1, -42), (0, 0), (true, "", -2005), (false, "0", 0)),
    ("digamma_two_pow_20_minus_1_p2048", "digamma", 2048, RoundingMode::ToEven, (1048575, 0), (1, -1), (false, "", -2043), (false, "", -2068)),
];

fn dyadic((n, e): (i64, i64), p: usize) -> Result<ExactNum, Box<dyn std::error::Error>> {
    let m =
        ExactNum::from_word(Word::try_from(n.unsigned_abs())?, p).ldexp(e, p, RoundingMode::None);
    Ok(if n < 0 { -m } else { m })
}

fn want((neg, hex, e): Part, p: usize, cc: &mut Consts) -> ExactNum {
    let m = ExactNum::parse(hex, Radix::Hex, p + 64, RoundingMode::None, cc).ldexp(
        e,
        p + 64,
        RoundingMode::None,
    );
    if neg {
        -m
    } else {
        m
    }
}

fn run(name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let &(_, f, p, rm, re, im, wre, wim) =
        CASES.iter().find(|c| c.0 == name).ok_or("no such case")?;
    let mut cc = Consts::new()?;
    let z = ExactComplex::new(dyadic(re, p)?, dyadic(im, p)?);
    let got = match f {
        "gamma" => z.gamma(p, rm, &mut cc),
        _ => z.digamma(p, rm, &mut cc),
    };
    assert!(!got.is_nan(), "{name}: NaN ({:?})", got.re().err());
    for (part, g, w) in [("re", got.re(), wre), ("im", got.im(), wim)] {
        let w = want(w, p, &mut cc);
        assert_eq!(
            g.compare(&w),
            Some(0),
            "{name} {part}: got {g:?}, want {w:?}"
        );
    }
    Ok(())
}

macro_rules! cases {
    ($($t:ident),* $(,)?) => {
        $(
            #[test]
            fn $t() -> Result<(), Box<dyn std::error::Error>> {
                run(stringify!($t))
            }
        )*
    };
}

cases!(
    gamma_three_quarters_quarter_i_p1920,
    gamma_three_quarters_quarter_i_p1984,
    gamma_three_quarters_quarter_i_p2048,
    gamma_three_quarters_minus_quarter_i_p1984,
    gamma_tiny_real_p2048_to_even,
    gamma_tiny_real_p2048_up,
    gamma_tiny_real_p2048_down,
    gamma_tiny_real_p2048_to_zero,
    gamma_tiny_real_p2048_from_zero,
    gamma_tiny_real_p2240,
    gamma_tiny_imag_p1984,
    gamma_two_pow_20_minus_1_p2048,
    gamma_two_pow_20_plus_1_p2048,
    gamma_two_pow_21_minus_1_p1984,
    gamma_two_pow_21_plus_1_p1984,
    digamma_three_quarters_quarter_i_p2048,
    digamma_tiny_real_p2048,
    digamma_two_pow_20_minus_1_p2048,
);
